package com.settingssearch;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;

final class SearchHistory
{
	private static final int LIMIT = 10;

	private final Gson gson;
	private final Supplier<String> load;
	private final Consumer<String> save;

	SearchHistory(Gson gson, Supplier<String> load, Consumer<String> save)
	{
		this.gson = gson;
		this.load = load;
		this.save = save;
	}

	List<Entry> entries()
	{
		return readEntries(load.get());
	}

	private List<Entry> readEntries(String value)
	{
		List<Entry> entries = new ArrayList<>();
		try
		{
			Entry[] stored = gson.fromJson(value, Entry[].class);
			if (stored != null)
			{
				for (Entry entry : stored)
				{
					if (entry != null && entry.query != null && !entry.query.isBlank())
					{
						entries.add(entry);
						if (entries.size() == LIMIT)
						{
							break;
						}
					}
				}
			}
		}
		catch (JsonParseException ignored)
		{
			// An invalid profile value is replaced when a new search is saved.
		}
		return entries;
	}

	void remember(String query, Setting setting)
	{
		String normalized = SettingSearch.normalize(query);
		if (normalized.isEmpty())
		{
			return;
		}

		String stored = load.get();
		List<Entry> recent = readEntries(stored);
		Entry previous = recent.stream()
			.filter(entry -> normalized.equals(SettingSearch.normalize(entry.query)))
			.findFirst().orElse(null);
		Entry next = setting == null
			? new Entry(query.strip(), previous)
			: new Entry(query.strip(), setting.name, setting.plugin, setting.key);
		recent.remove(previous);
		recent.add(0, next);
		String updated = gson.toJson(recent.subList(0, Math.min(recent.size(), LIMIT)));
		if (!updated.equals(stored))
		{
			save.accept(updated);
		}
	}

	static final class Entry
	{
		final String query;
		final String settingName;
		final String plugin;
		final String settingKey;

		private Entry(String query, Entry previous)
		{
			this(query, previous == null ? null : previous.settingName, previous == null ? null : previous.plugin,
				previous == null ? null : previous.settingKey);
		}

		private Entry(String query, String settingName, String plugin, String settingKey)
		{
			this.query = query;
			this.settingName = settingName;
			this.plugin = plugin;
			this.settingKey = settingKey;
		}

		boolean matches(Setting setting)
		{
			return setting.plugin.equals(plugin) && setting.key.equals(settingKey);
		}
	}
}

package com.settingssearch;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

final class Setting
{
	private static final Pattern CAMEL_CASE = Pattern.compile("(?<=[a-z0-9])(?=[A-Z])");

	final String name;
	final String plugin;
	final String section;
	final String description;
	final String key;
	final Runnable open;
	final String normalizedName;
	final List<List<String>> searchFields;

	Setting(String name, String plugin, String section, String description,
		String key, String[] tags, Runnable open)
	{
		this.name = name;
		this.plugin = plugin;
		this.section = section;
		this.description = description;
		this.key = key;
		this.open = open;
		normalizedName = SettingSearch.normalize(name);
		searchFields = new ArrayList<>();
		for (String field : List.of(name, section, plugin, key + " " + CAMEL_CASE.matcher(key).replaceAll(" "),
			description, String.join(" ", tags)))
		{
			searchFields.add(SettingSearch.words(field));
		}
	}

	String location()
	{
		return section.isBlank() ? plugin : plugin + " / " + section;
	}
}

package com.settingssearch;

import java.text.Normalizer;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

final class SettingSearch
{

	private static final Pattern ACCENTS = Pattern.compile("\\p{M}+");
	private static final Pattern SEPARATORS = Pattern.compile("[^\\p{L}\\p{N}]+");
	private static final int[] FIELD_WEIGHTS = {32, 18, 16, 12, 7, 5};

	private SettingSearch()
	{
	}

	static String normalize(String value)
	{

		String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
		String plain = ACCENTS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
		return SEPARATORS.matcher(plain).replaceAll(" ").strip();
	}

	static List<String> words(String value)
	{
		String normalized = normalize(value);
		return normalized.isEmpty() ? List.of() : List.of(normalized.split(" "));
	}

	static List<Setting> find(List<Setting> index, String query, boolean fuzzy)
	{
		String phrase = normalize(query);
		if (phrase.isEmpty())
		{
			return List.of();
		}
		List<String> terms = List.of(phrase.split(" "));
		List<Map<String, Integer>> scoresByWord = new ArrayList<>();
		for (String ignored : terms)
		{
			scoresByWord.add(new HashMap<>());
		}
		List<Match> matches = new ArrayList<>();
		for (Setting setting : index)
		{
			int score = 0;
			for (int i = 0; i < terms.size(); i++)
			{
				int termScore = scoreTerm(setting, terms.get(i), fuzzy, scoresByWord.get(i));
				if (termScore == 0)
				{
					score = 0;
					break;
				}
				score += termScore;
			}
			if (score > 0)
			{
				if (setting.normalizedName.equals(phrase))
				{
					score += 80;
				}
				else if ((" " + setting.normalizedName + " ").contains(" " + phrase + " "))
				{
					score += 40;
				}
				matches.add(new Match(setting, score));
			}
		}
		matches.sort(Comparator.comparingInt((Match match) -> match.score).reversed()
			.thenComparing(match -> match.setting.name, String.CASE_INSENSITIVE_ORDER)
			.thenComparing(match -> match.setting.location(), String.CASE_INSENSITIVE_ORDER));
		List<Setting> result = new ArrayList<>(matches.size());
		for (Match match : matches)
		{
			result.add(match.setting);
		}
		return result;
	}

	private static int scoreTerm(Setting setting, String term, boolean fuzzy, Map<String, Integer> cache)
	{
		int best = 0;
		for (int i = 0; i < FIELD_WEIGHTS.length; i++)
		{
			for (String word : setting.searchFields.get(i))
			{
				int score = cache.computeIfAbsent(word, candidate -> scoreWord(term, candidate, fuzzy));
				if (score > 0)
				{
					best = Math.max(best, score + FIELD_WEIGHTS[i]);
				}
			}
		}
		return best;
	}

	private static int scoreWord(String term, String word, boolean fuzzy)
	{
		if (word.equals(term))
		{
			return 100;
		}
		if (word.startsWith(term))
		{
			return 75;
		}
		if (term.length() >= 3 && word.contains(term))
		{
			return 54;
		}
		int limit = term.length() >= 8 ? 2 : 1;
		if (!fuzzy || term.length() < 4 || Math.abs(word.length() - term.length()) > limit)
		{
			return 0;
		}
		int distance = editDistance(term, word);
		return distance <= limit ? 30 - 8 * (distance - 1) : 0;
	}

	// Optimal string alignment counts one adjacent transposition as one edit.
	private static int editDistance(String term, String word)
	{
		int[] twoBack = new int[word.length() + 1];
		int[] previous = new int[word.length() + 1];
		int[] current = new int[word.length() + 1];
		for (int j = 0; j <= word.length(); j++)
		{
			previous[j] = j;
		}
		for (int i = 1; i <= term.length(); i++)
		{
			current[0] = i;
			for (int j = 1; j <= word.length(); j++)
			{
				int substitution = term.charAt(i - 1) == word.charAt(j - 1) ? 0 : 1;
				current[j] = Math.min(Math.min(previous[j] + 1, current[j - 1] + 1),
					previous[j - 1] + substitution);
				if (i > 1 && j > 1 && term.charAt(i - 1) == word.charAt(j - 2)
					&& term.charAt(i - 2) == word.charAt(j - 1))
				{
					current[j] = Math.min(current[j], twoBack[j - 2] + 1);
				}
			}
			int[] reuse = twoBack;
			twoBack = previous;
			previous = current;
			current = reuse;
		}
		return previous[word.length()];
	}

	private static final class Match
	{
		private final Setting setting;
		private final int score;

		private Match(Setting setting, int score)
		{
			this.setting = setting;
			this.score = score;
		}
	}
}

package com.settingssearch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SettingsSearchConfig.GROUP)
public interface SettingsSearchConfig extends Config
{
	String GROUP = "settings-search";
	String FUZZY_KEY = "fuzzySearch";
	String HISTORY_KEY = "searchHistory";
	String FUZZY_DESCRIPTION = "Finds close matches for typos, for example “notificaiton” also finds “notification”. "
		+ "Turn this off to match only the letters you type.";

	@ConfigItem(keyName = FUZZY_KEY, name = "Fuzzy search", description = FUZZY_DESCRIPTION)
	default boolean fuzzySearch()
	{
		return true;
	}
}

