import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Settings Search",
	description = "Find individual settings across installed plugins",
	tags = {"config", "settings", "fuzzy", "search"}
)
public class SettingsSearchPlugin extends Plugin
{
	@Inject
	private PluginManager pluginManager;
	@Inject
	private ConfigManager configManager;
	@Inject
	private SettingsSearchConfig config;
	@Inject
	private Gson gson;
	@Inject
	private ClientToolbar toolbar;
	@Inject
	private EventBus eventBus;

	// Panel and navigation are owned by Swing's event dispatch thread.
	private SettingsSearchPanel panel;
	private NavigationButton navigation;

	@Override
	protected void startUp()
	{
		SearchHistory history = new SearchHistory(gson,
			() -> configManager.getConfiguration(SettingsSearchConfig.GROUP, SettingsSearchConfig.HISTORY_KEY),
			value -> configManager.setConfiguration(SettingsSearchConfig.GROUP, SettingsSearchConfig.HISTORY_KEY, value));
		panel = new SettingsSearchPanel(this::buildIndex, config::fuzzySearch,
			enabled -> configManager.setConfiguration(SettingsSearchConfig.GROUP, SettingsSearchConfig.FUZZY_KEY, enabled),
			history);
		navigation = NavigationButton.builder()
			.tooltip("Settings Search")
			.icon(searchIcon(ColorScheme.LIGHT_GRAY_COLOR))
			.priority(1)
			.panel(panel)
			.build();
		toolbar.addNavigation(navigation);
	}

	@Override
	protected void shutDown()
	{
		if (navigation != null)
		{
			toolbar.removeNavigation(navigation);
			panel.onDeactivate();
			navigation = null;
			panel = null;
		}
	}

	@Provides
	SettingsSearchConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(SettingsSearchConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SettingsSearchConfig.GROUP.equals(event.getGroup())
			&& SettingsSearchConfig.FUZZY_KEY.equals(event.getKey()))
		{
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.refreshFuzzySetting();
				}
			});
		}
	}

	@Subscribe
	public void onExternalPluginsChanged(ExternalPluginsChanged event)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.invalidateIndex();
			}
		});
	}

	private List<Setting> buildIndex()
	{
		List<Setting> settings = new ArrayList<>();
		addSettings(settings, configManager.getConfig(RuneLiteConfig.class),
			namedTarget("RuneLite"), new String[]{"client"});
		addSettings(settings, configManager.getConfig(ChatColorConfig.class),
			namedTarget("Chat Color"), new String[]{"colour", "messages"});
		for (Plugin plugin : pluginManager.getPlugins())
		{
			PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
			if (plugin != this && descriptor != null && !descriptor.hidden())
			{
				Config config = pluginManager.getPluginConfigProxy(plugin);
				if (config != null)
				{
					addSettings(settings, config, plugin, descriptor.tags());
				}
			}
		}
		return settings;
	}

	private void addSettings(List<Setting> settings, Config config, Plugin plugin, String[] tags)
	{
		ConfigDescriptor configDescriptor = configManager.getConfigDescriptor(config);
		Map<String, String> sections = new HashMap<>();
		for (ConfigSectionDescriptor section : configDescriptor.getSections())
		{
			sections.put(section.getKey(), plainText(section.getSection().name()));
		}
		for (ConfigItemDescriptor itemDescriptor : configDescriptor.getItems())
		{
			ConfigItem item = itemDescriptor.getItem();
			if (!item.hidden())
			{
				settings.add(new Setting(plainText(item.name()), plugin.getName(),
					sections.getOrDefault(item.section(), ""), plainText(item.description()),
					item.keyName(), tags, () -> openConfiguration(plugin)));
			}
		}
	}

	private static String plainText(String value)
	{
		return Text.removeTags(value.replaceAll("(?i)<br\\s*/?>", " ")).strip();
	}

	private void openConfiguration(Plugin plugin)
	{
		// RuneLite uses this event to open a plugin's settings from an overlay menu.
		// This overlay is never registered or displayed.
		Overlay target = new Overlay(plugin)
		{
			@Override
			public Dimension render(Graphics2D graphics)
			{
				return null;
			}
		};
		eventBus.post(new OverlayMenuClicked(
			new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, "Configure", plugin.getName()), target));
	}

	private static Plugin namedTarget(String name)
	{
		// The two client settings pages are listed by name without a plugin instance.
		return new Plugin()
		{
			@Override
			public String getName()
			{
				return name;
			}
		};
	}

	static BufferedImage searchIcon(Color color)
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setColor(color);
			graphics.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			graphics.drawOval(2, 2, 8, 8);
			graphics.drawLine(9, 9, 14, 14);
		}
		finally
		{
			graphics.dispose();
		}
		return icon;
	}
}

package com.settingssearch;

import com.google.gson.Gson;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SearchHistoryTest
{
	private final AtomicReference<String> saved = new AtomicReference<>();
	private final SearchHistory history = new SearchHistory(new Gson(), saved::get, saved::set);

	@Test
	public void restoresSearchAndSelectedSettingFromProfile()
	{
		Setting target = new Setting("Zoom limit", "Camera", "Zoom", "", "zoomLimit", new String[0], () -> {});
		history.remember("Zoom", target);
		history.remember(" zoom ", null);

		SearchHistory restored = new SearchHistory(new Gson(), saved::get, saved::set);
		assertEquals(1, restored.entries().size());
		SearchHistory.Entry entry = restored.entries().get(0);
		assertEquals("zoom", entry.query);
		assertEquals("Zoom limit", entry.settingName);
		assertTrue(entry.matches(target));
		assertFalse(entry.matches(new Setting("Zoom limit", "Camera", "Zoom", "", "anotherKey",
			new String[0], () -> {})));
	}

	@Test
	public void keepsOnlyRecentSearchesAndRecoversFromInvalidStoredData()
	{
		saved.set("invalid JSON");
		assertTrue(history.entries().isEmpty());
		history.remember(" ", null);
		assertEquals("invalid JSON", saved.get());

		for (int i = 0; i <= 10; i++)
		{
			history.remember("Search " + i, null);
		}
		assertEquals(10, history.entries().size());
		assertEquals("Search 10", history.entries().get(0).query);
		assertEquals("Search 1", history.entries().get(9).query);
	}
}

package com.settingssearch;

import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class SettingSearchTest
{
	private final Setting notification = setting("Idle Notification", "Idle Notifier", "Alerts",
		"Warn when you stop interacting", "idleNotification");
	private final Setting descriptionMatch = setting("Screen Flash", "RuneLite", "Notifications",
		"Flash the screen when a notification arrives", "flashNotification");
	private final List<Setting> index = List.of(descriptionMatch, notification);

	@Test
	public void ranksSettingNamesAboveOtherFields()
	{
		assertEquals(List.of(notification, descriptionMatch), SettingSearch.find(index, "notification", true));
		assertEquals(notification, SettingSearch.find(index, "idle notification", true).get(0));
	}

	@Test
	public void combinesWordsFromDifferentFieldsInEitherOrder()
	{
		assertEquals(List.of(notification), SettingSearch.find(index, "alerts notifier interacting", false));
		assertEquals(List.of(descriptionMatch), SettingSearch.find(index, "flash runelite", false));
	}

	@Test
	public void acceptsAdjacentTranspositionsAndNormalTyposOnlyInFuzzyMode()
	{
		assertEquals(notification, SettingSearch.find(index, "notificaiton", true).get(0));
		assertEquals(List.of(notification), SettingSearch.find(index, "notifierr", true));
		assertTrue(SettingSearch.find(index, "notificaiton", false).isEmpty());
		assertTrue(SettingSearch.find(index, "zx", true).isEmpty());
	}

	@Test
	public void normalizesCaseAccentsPunctuationAndPartialWords()
	{
		assertEquals(List.of(notification), SettingSearch.find(index, "  IDLE, NOTIF!  ", false));
		assertEquals(List.of(notification), SettingSearch.find(index, "alérts", false));
		assertTrue(SettingSearch.find(index, " ! ", true).isEmpty());
	}

	private static Setting setting(String name, String plugin, String section, String description, String key)
	{
		return new Setting(name, plugin, section, description, key, new String[0], () -> {});
	}
}

